mapper.update:

UPDATE DB_OFF_IV A	
   SET A.DS_QTY=#{DS_QTY}	
WHERE A.BUYER=#{BUYER}	
AND A.ADD_DATE=#{ADD_DATE}	
AND A.SEQ=#{SEQ}	
AND A.DS_SEQ=#{DS_SEQ}	
AND A.STATUS  ^='D'


UPDATE DB_OFF_PO A	
	  SET A.PR_QTY=(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.ITEM_AMT=A.UNIT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.AGENT_ITEM_AMT=A.AGENT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D')              	
 WHERE A.BUYER=#{BUYER}	
	 AND A.ADD_DATE=#{ADD_DATE}	
	 AND A.SEQ=#{SEQ}


UPDATE DB_OFF_IV A	
   SET A.DS_QTY=#{DS_QTY},	
	   A.PO_QTY=#{DS_QTY}	
WHERE A.BUYER=#{BUYER}	
AND A.ADD_DATE=#{ADD_DATE}	
AND A.SEQ=#{SEQ}	
AND A.DS_SEQ=#{DS_SEQ}	
AND A.STATUS  ^='D'


UPDATE DB_OFF_PO A	
	  SET A.PR_QTY=(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.PO_QTY=(SELECT SUM(NVL(PO_QTY,0)) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.ITEM_AMT=A.UNIT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.AGENT_ITEM_AMT=A.AGENT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D')              	
 WHERE A.BUYER=#{BUYER}	
	 AND A.ADD_DATE=#{ADD_DATE}	
	 AND A.SEQ=#{SEQ}


UPDATE DB_OFF_PO A	
	  SET A.PR_QTY=(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.PO_QTY=(SELECT SUM(NVL(PO_QTY,0)) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.DO_QTY=(SELECT SUM(NVL(PO_QTY,0)) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D' AND DS_DATE IS NOT NULL),	
			 A.ITEM_AMT=A.UNIT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D'),	
			 A.AGENT_ITEM_AMT=A.AGENT_PRICE*(SELECT SUM(DS_QTY) FROM DB_OFF_IV WHERE BUYER=A.BUYER AND ADD_DATE=A.ADD_DATE AND SEQ=A.SEQ AND STATUS ^='D')              	
 WHERE A.BUYER=#{BUYER}	
	 AND A.ADD_DATE=#{ADD_DATE}	
	 AND A.SEQ=#{SEQ}


UPDATE DB_OFF_PO A	
   SET A.PLANT=#{PLANT},	
	   A.OPKG_SEQ=#{OPKG_SEQ},	
	   A.OPKG_RD_DATE=#{RD_DATE}	
 WHERE A.BUYER=#{st_off_buyer}	
   AND A.ADD_DATE=#{st_off_add_date}	
   AND A.SEQ=#{st_off_seq}
